<?php require_once __DIR__ . '/layout.php';
$reasons=load_data('reasons'); $edit=null;
if(isset($_GET['delete'])){ save_data('reasons', delete_by_id($reasons,(int)$_GET['delete'])); redirect('reasons.php'); }
if(isset($_GET['edit'])) $edit=find_by_id($reasons,(int)$_GET['edit']);
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0); $name=trim($_POST['name']); if($name!==''){ if($id){ foreach($reasons as &$r) if((int)$r['id']===$id){$r['name']=$name; break;} } else $reasons[]=['id'=>next_id($reasons),'name'=>$name]; save_data('reasons',$reasons);} redirect('reasons.php'); }
$reasons=reasons_all(); page_header('Request reasons','reasons'); ?><div class="card"><h2><?= $edit?'Edit reason':'Add reason' ?></h2><form method="post"><input type="hidden" name="id" value="<?= h($edit['id']??'') ?>"><div><label>Reason name</label><input name="name" required value="<?= h($edit['name']??'') ?>"></div><button class="btn">Save</button></form></div><div class="card"><h2>Reason list</h2><table><thead><tr><th>Reason</th><th></th></tr></thead><tbody><?php foreach($reasons as $r): ?><tr><td><?= h($r['name']) ?></td><td class="actions"><a class="btn small" href="reasons.php?edit=<?= (int)$r['id'] ?>">Edit</a><a class="btn small danger" onclick="return confirm('Delete this reason?')" href="reasons.php?delete=<?= (int)$r['id'] ?>">Delete</a></td></tr><?php endforeach; ?></tbody></table></div><?php page_footer(); ?>
